xpath.script:
//
(function() {
    'use strict';
    var MicrositeSearchable = {
        init: function() {
            var selects = document.querySelectorAll('.microsite-cat-select:not([data-searchable="true"])');
            selects.forEach(function(select) { this.enhanceSelect(select); }.bind(this));
        },
        enhanceSelect: function(select) {
            select.dataset.searchable = 'true';
            var form = select.closest('form');
            var wrapper = document.createElement('div');
            wrapper.className = 'microsite-searchable-wrapper';
            wrapper.style.cssText = 'position:relative;display:block;z-index:9999;width:100%;';
            var toggle = document.createElement('button');
            toggle.type = 'button';
            toggle.className = 'form-select text-start microsite-searchable-toggle';
            var selectedOption = select.options[select.selectedIndex];
            toggle.innerHTML = '<span class="selected-text">' + (selectedOption ? selectedOption.text : 'Seleccione...') + '</span>';
            var dropdown = document.createElement('div');
            dropdown.className = 'microsite-searchable-dropdown';
            dropdown.style.cssText = 'position:absolute;z-index:99999;background:#fff;border:1px solid #ced4da;border-radius:0.375rem;width:100%;max-height:300px;overflow:hidden;display:none;box-shadow:0 0.5rem 1rem rgba(0,0,0,0.15);top:100%;left:0;margin-top:2px;';
            var searchContainer = document.createElement('div');
            searchContainer.className = 'p-2 border-bottom';
            searchContainer.innerHTML = '<input type="text" class="form-control form-control-sm" placeholder="Buscar categoría..." autocomplete="off">';
            var searchInput = searchContainer.querySelector('input');
            var list = document.createElement('div');
            list.className = 'microsite-searchable-options';
            list.style.cssText = 'max-height:220px;overflow-y:auto;';
            Array.from(select.options).forEach(function(opt, index) {
                var item = document.createElement('div');
                item.className = 'microsite-searchable-option';
                if (index === 0) item.classList.add('text-muted');
                item.textContent = opt.text;
                item.dataset.value = opt.value;
                item.style.cssText = 'padding:8px 12px;cursor:pointer;transition:background 0.15s;font-size:14px;border-bottom:1px solid #f0f0f0;';
                item.addEventListener('mouseenter', function() { if (this.style.background !== 'rgb(113, 75, 103)') this.style.background = '#e9ecef'; });
                item.addEventListener('mouseleave', function() { if (this.style.background !== 'rgb(113, 75, 103)') this.style.background = 'transparent'; });
                item.addEventListener('click', function(e) {
                    e.stopPropagation();
                    select.value = opt.value;
                    toggle.querySelector('.selected-text').textContent = opt.text;
                    dropdown.style.display = 'none';
                    list.querySelectorAll('.microsite-searchable-option').forEach(function(el) { el.style.background = 'transparent'; el.style.color = 'inherit'; });
                    this.style.background = '#714B67';
                    this.style.color = '#fff';
                    if (form) form.submit();
                });
                list.appendChild(item);
            });
            searchInput.addEventListener('input', function() {
                var term = this.value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                list.querySelectorAll('.microsite-searchable-option').forEach(function(item) {
                    var text = item.textContent.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                    item.style.display = text.includes(term) ? 'block' : 'none';
                });
            });
            var positionDropdown = function() {
                var rect = toggle.getBoundingClientRect();
                var viewportHeight = window.innerHeight;
                var spaceBelow = viewportHeight - rect.bottom;
                var dropdownHeight = 250;
                if (spaceBelow < dropdownHeight && rect.top > dropdownHeight) {
                    dropdown.style.top = 'auto';
                    dropdown.style.bottom = '100%';
                    dropdown.style.marginTop = '0';
                    dropdown.style.marginBottom = '4px';
                } else {
                    dropdown.style.top = '100%';
                    dropdown.style.bottom = 'auto';
                    dropdown.style.marginTop = '2px';
                    dropdown.style.marginBottom = '0';
                }
            };
            toggle.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                var isOpen = dropdown.style.display === 'block';
                document.querySelectorAll('.microsite-searchable-dropdown').forEach(function(d) { if (d !== dropdown) d.style.display = 'none'; });
                if (!isOpen) {
                    positionDropdown();
                    dropdown.style.display = 'block';
                    searchInput.value = '';
                    searchInput.focus();
                    list.querySelectorAll('.microsite-searchable-option').forEach(function(item) { item.style.display = 'block'; });
                } else {
                    dropdown.style.display = 'none';
                }
            });
            document.addEventListener('click', function(e) {
                if (!dropdown.contains(e.target) && e.target !== toggle) dropdown.style.display = 'none';
            });
            dropdown.addEventListener('click', function(e) { if (e.target !== searchInput) e.stopPropagation(); });
            window.addEventListener('resize', function() { if (dropdown.style.display === 'block') positionDropdown(); }, { passive: true });
            dropdown.appendChild(searchContainer);
            dropdown.appendChild(list);
            wrapper.appendChild(dropdown);
            wrapper.appendChild(toggle);
            select.style.display = 'none';
            select.parentNode.insertBefore(wrapper, select);
            wrapper.appendChild(select);
        }
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() { MicrositeSearchable.init(); });
    } else {
        MicrositeSearchable.init();
    }
})();
//
